// Variables globales de autenticación
let usuarioActual = null;

// Verificar si estamos en la página de admin
const esPaginaAdmin = window.location.pathname.includes('admin.html');

function inicializarAuth() {
    // Manejar el resultado de redirección primero
    manejarRedirectResult();
    
    // Configurar el listener de estado de autenticación
    firebase.auth().onAuthStateChanged(async (user) => {
        usuarioActual = user;

        // Google pisa displayName con el nombre de la cuenta de Google en
        // cada login (por eso un nombre editado a mano "desaparecía" al
        // cerrar sesión y volver a entrar, aunque updateProfile() sí se
        // había guardado bien la vez anterior) — si el usuario ya había
        // elegido un nombre propio, se reaplica acá antes de pintar nada.
        await restaurarNombrePersonalizado(user);

        // Solo actualizar UI si no estamos en admin
        if (!esPaginaAdmin) {
            await actualizarUIUsuario(user);
            await actualizarBotonAdmin(user);

            if (user && window.cargarDatosUsuario) {
                await cargarDatosUsuario(user.uid);
            }
        }
    });

    if (!esPaginaAdmin) {
        configurarEventosAuth();
    }
}

function configurarEventosAuth() {
    // Eliminar event listeners anteriores para evitar duplicados
    document.removeEventListener('click', manejarClicAuth);

    // Nuevo manejador unificado
    document.addEventListener('click', manejarClicAuth);

    inicializarEdicionNombreUsuario();
}

// Firebase Auth vuelve a copiar el nombre de la cuenta de Google sobre
// displayName en cada login vía Google (no solo en el alta inicial) — así
// que updateProfile() se guarda bien, pero la próxima vez que el usuario
// inicia sesión, Google se lo pisa de nuevo. Por eso el nombre elegido a
// mano se guarda APARTE en Firestore (usuarios/{uid}.nombrePersonalizado,
// ver guardarNuevoNombreUsuario) y se reaplica acá en cada login, antes
// de pintar cualquier cosa.
async function restaurarNombrePersonalizado(user) {
    if (!user || user.isAnonymous) return;
    try {
        const doc = await window.db.collection('usuarios').doc(user.uid).get();
        const nombrePersonalizado = doc.exists ? doc.data().nombrePersonalizado : null;
        if (nombrePersonalizado && nombrePersonalizado !== user.displayName) {
            await user.updateProfile({ displayName: nombrePersonalizado });
        }
    } catch (error) {
        console.error('Error restaurando nombre personalizado:', error);
    }
}

// Google asigna un displayName por defecto que muchas personas nunca
// cambian (ej. el nombre de su cuenta de Gmail tal cual) — esto deja
// editarlo desde el submenú "Perfil" sin salir del sitio.
function activarEdicionNombre() {
    const p = document.getElementById('usuario-nombre');
    const input = document.getElementById('usuario-nombre-input');
    if (!p || !input) return;
    input.value = usuarioActual?.displayName || '';
    p.style.display = 'none';
    input.style.display = '';
    input.focus();
    input.select();
}

function cancelarEdicionNombre() {
    const p = document.getElementById('usuario-nombre');
    const input = document.getElementById('usuario-nombre-input');
    if (!p || !input) return;
    input.style.display = 'none';
    p.style.display = '';
}

async function guardarNuevoNombreUsuario(nuevoNombre) {
    // Respaldo del filtrado en vivo del input (por si el valor llegó acá
    // sin pasar por el evento "input", ej. autocompletado del navegador).
    const nombre = sanitizarNombreUsuario(nuevoNombre.trim()).trim();
    if (!nombre || !usuarioActual || nombre === usuarioActual.displayName) {
        cancelarEdicionNombre();
        return;
    }
    const nombreAnterior = usuarioActual.displayName;
    try {
        await usuarioActual.updateProfile({ displayName: nombre });

        // Google vuelve a pisar displayName con el nombre de la cuenta de
        // Google en el próximo login (ver restaurarNombrePersonalizado) —
        // sin guardarlo también acá, el cambio se "perdía" apenas el
        // usuario cerraba sesión y volvía a entrar.
        await window.db.collection('usuarios').doc(usuarioActual.uid).set(
            { nombrePersonalizado: nombre },
            { merge: true }
        );

        // updateProfile() actualiza displayName en el propio usuarioActual
        // al toque — re-renderizar con la misma función de siempre
        // mantiene el nombre consistente en todos lados (menú, submenú)
        // sin tener que tocar cada lugar a mano.
        await actualizarUIUsuario(usuarioActual);
        guardarUsuario(usuarioActual);

        // El campo "Nombre completo" del paso 4 (y por lo tanto el resumen
        // de los pasos 5/6, que solo leen lo que hay tipeado ahí) se
        // autocompleta una única vez con el displayName de la cuenta y
        // después nunca se vuelve a tocar — si seguía teniendo ese mismo
        // valor viejo (o sea, el cliente nunca lo editó a mano), lo
        // actualizamos acá para que quede en sincro. Si el campo tiene
        // otra cosa (lo escribió a mano, o está reservando para otra
        // persona), no lo tocamos.
        const nombreInput = document.getElementById('nombre');
        if (nombreInput && nombreInput.value === nombreAnterior) {
            nombreInput.value = nombre;
            if (typeof validarNombre === 'function') validarNombre();
            if (typeof guardarDatosFormulario === 'function') guardarDatosFormulario();
            if (typeof actualizarResumen === 'function') actualizarResumen();
        }
    } catch (error) {
        console.error('Error actualizando el nombre del usuario:', error);
        mostrarError('No se pudo actualizar el nombre. Intentá de nuevo.');
    } finally {
        cancelarEdicionNombre();
    }
}

const LIMITE_NOMBRE_USUARIO = 25;

// Letras (con tildes/ñ), espacios, guion y apóstrofe — cubre nombres
// compuestos ("María José") y apellidos con guion ("Pérez-Gómez") o
// apóstrofe ("O'Connor") sin permitir números ni símbolos random.
function sanitizarNombreUsuario(texto) {
    return texto
        .replace(/[^a-zA-ZÀ-ÖØ-öø-ÿñÑ\s'-]/g, '')
        .slice(0, LIMITE_NOMBRE_USUARIO);
}

function inicializarEdicionNombreUsuario() {
    const input = document.getElementById('usuario-nombre-input');
    if (!input || input.dataset.wired) return;
    input.dataset.wired = 'true';

    input.addEventListener('input', () => {
        const limpio = sanitizarNombreUsuario(input.value);
        if (limpio !== input.value) input.value = limpio;
    });

    input.addEventListener('keydown', (e) => {
        if (e.key === 'Enter') {
            e.preventDefault();
            guardarNuevoNombreUsuario(input.value);
        } else if (e.key === 'Escape') {
            e.preventDefault();
            cancelarEdicionNombre();
        }
    });

    input.addEventListener('blur', () => {
        if (input.style.display !== 'none') {
            guardarNuevoNombreUsuario(input.value);
        }
    });
}

async function manejarClicAuth(e) {
    // Verificar si el clic fue en un botón de auth
    const esBotonAuthPrincipal = e.target.id === 'btn-google' || e.target.closest('#btn-google');
    const esBotonAuthMenu = e.target.id === 'btn-google-menu' || e.target.closest('#btn-google-menu');
    
    if (esBotonAuthPrincipal || esBotonAuthMenu) {
        e.preventDefault();
        e.stopPropagation();
        
        // Ejecutar inmediatamente, no async
        iniciarSesionGoogle();
        return;
    }
    
    // Otros eventos...
    if (e.target.id === 'nav-cerrar-sesion' || e.target.closest('#nav-cerrar-sesion')) {
        e.preventDefault();
        cerrarSesion();
        return;
    }
    
    // Va ANTES que el chequeo de #nav-perfil a propósito: el botón vive
    // anidado adentro de ese link (#nav-perfil envuelve todo el bloque de
    // Perfil, incluido su submenú), así que closest('#nav-perfil') también
    // da true al clickear el lápiz — si ese chequeo corriera primero,
    // absorbía el click entero y manejarOpcionProtegida('perfil') se
    // ejecutaba en vez de activar la edición.
    if (e.target.id === 'btn-editar-nombre' || e.target.closest('#btn-editar-nombre')) {
        e.preventDefault();
        e.stopPropagation();
        activarEdicionNombre();
        return;
    }

    if (e.target.id === 'nav-perfil' || e.target.closest('#nav-perfil')) {
        e.preventDefault();
        manejarOpcionProtegida('perfil');
        return;
    }

    if (e.target.id === 'nav-mis-turnos' || e.target.closest('#nav-mis-turnos')) {
        e.preventDefault();
        manejarOpcionProtegida('mis-turnos');
        return;
    }
    
    if (e.target.classList.contains('.btn-admin')) {
        e.preventDefault();
        if (usuarioActual && await esUsuarioAdministrador(usuarioActual)) {
            window.location.href = '/admin.html';
        } else {
            mostrarError('Acceso denegado. Debes ser administrador.');
        }
        return;
    }
}

async function iniciarSesionGoogle() {
    // Deshabilitar botones temporalmente para evitar múltiples clics
    deshabilitarBotonesAuth(true);
    
    try {
        const provider = new firebase.auth.GoogleAuthProvider();
        
        // Configuración adicional para el popup
        provider.setCustomParameters({
            prompt: 'select_account'
        });
        
        // Intentar con popup primero
        const result = await firebase.auth().signInWithPopup(provider);
        await manejarPrimerLoginSiCorresponde(result.user);

    } catch (error) {
        console.error('Error en autenticación:', error);
        
        // Manejar diferentes tipos de errores
        if (error.code === 'auth/popup-blocked') {
            await manejarAutenticacionRedirect();
        } else if (error.code === 'auth/popup-closed-by-user') {
            mostrarError('Cerraste la ventana de autenticación. Intenta nuevamente.');
        } else {
            mostrarErrorAuth(error);
        }
    } finally {
        deshabilitarBotonesAuth(false);
    }
}

async function manejarAutenticacionRedirect() {
    try {
        const provider = new firebase.auth.GoogleAuthProvider();
        provider.setCustomParameters({
            prompt: 'select_account'
        });
        
        // Guardar la URL actual para redirigir después
        sessionStorage.setItem('preAuthUrl', window.location.href);
        
        await firebase.auth().signInWithRedirect(provider);
    } catch (redirectError) {
        console.error('Error en redirección:', redirectError);
        mostrarError('No se pudo iniciar sesión. Por favor, habilita las ventanas emergentes para este sitio.');
    }
}

// Manejar el resultado de la redirección al cargar la página
function manejarRedirectResult() {
    firebase.auth().getRedirectResult().then(async (result) => {
        if (result.user) {
            await manejarPrimerLoginSiCorresponde(result.user);

            // Redirigir a la URL original si existe
            const preAuthUrl = sessionStorage.getItem('preAuthUrl');
            if (preAuthUrl && preAuthUrl !== window.location.href) {
                sessionStorage.removeItem('preAuthUrl');
                window.location.href = preAuthUrl;
            }
        }
    }).catch((error) => {
        console.error('Error en resultado de redirección:', error);
    });
}

// Primer login del usuario en TODA la plataforma (no por negocio — un
// mismo cliente puede reservar en varios negocios con la misma cuenta).
// usuarios/{uid} hoy no lo crea nadie más; esta transacción es la única
// escritura. Si dos pestañas/dispositivos loguean casi al mismo tiempo a
// un usuario genuinamente nuevo, solo la escritura que efectivamente crea
// el documento dispara el email — la otra ve el doc ya creado y no hace nada.
async function manejarPrimerLoginSiCorresponde(user) {
    if (!user) return;
    try {
        const userRef = window.db.collection('usuarios').doc(user.uid);
        let esNuevo = false;

        await window.db.runTransaction(async (tx) => {
            const doc = await tx.get(userRef);
            if (doc.exists) return;
            tx.set(userRef, {
                nombre: user.displayName || '',
                creadoEl: firebase.firestore.FieldValue.serverTimestamp()
            });
            esNuevo = true;
        });

        if (esNuevo) {
            await firebase.functions().httpsCallable('enviarEmailBienvenida')({
                negocioId: obtenerNegocioIdActual()
            });
        }
    } catch (error) {
        console.error('Error en manejo de primer login:', error);
    }
}

async function cerrarSesion() {
    try {
        // signOut() siempre se resuelve exitosamente, no necesita try-catch
        await firebase.auth().signOut();
        
        // Opcional: Redirigir a la página principal o recargar
        setTimeout(() => {
            window.location.reload(); // O window.location.href = '/';
        }, 1000);
        
    } catch (error) {
        // Este bloque casi nunca se ejecutará porque signOut() siempre tiene éxito
        console.warn('Advertencia inesperada al cerrar sesión:', error);
        // Pero aún así mostramos éxito porque la sesión se cerró
        mostrarMensajeExito('Sesión cerrada correctamente');
    }
}

