// Función para mostrar errores de autenticación
function mostrarErrorAuth(error) {
    let mensaje = 'Error al autenticar';
    
    const erroresConocidos = {
        'auth/popup-blocked': 'El navegador bloqueó la ventana de inicio de sesión. Por favor, permite ventanas emergentes para este sitio.',
        'auth/popup-closed-by-user': 'Cerraste la ventana de inicio de sesión. Intenta nuevamente.',
        'auth/cancelled-popup-request': 'Solicitud cancelada.',
        'auth/operation-not-allowed': 'Esta operación no está permitida. Contacta al administrador.',
        'auth/operation-not-supported-in-this-environment': 'Este navegador no soporta la autenticación con popup.',
        'auth/unauthorized-domain': 'Este dominio no está autorizado para autenticación.'
    };
    
    mensaje = erroresConocidos[error.code] || error.message || 'Error desconocido al autenticar';
    
    // Usar tu función existente de mostrarError
    if (typeof mostrarError === 'function') {
        mostrarError(mensaje);
    } else {
        alert(mensaje); // Fallback
    }
}

// Guardar datos del usuario en LocalStorage
function guardarUsuario(user) {
    localStorage.setItem('usuario', JSON.stringify({
        uid: user.uid,
        nombre: user.displayName,
        email: user.email,
        photoURL: user.photoURL
    }));
}

// Limpiar datos del usuario
function limpiarUsuario() {
    localStorage.removeItem('usuario');
}

