function autocompletarFormulario(user) {
    const nombreInput = document.getElementById('nombre');
    const emailInput = document.getElementById('email');
    
    if (nombreInput && !nombreInput.value && user.displayName) {
        nombreInput.value = user.displayName;
        validarNombre(); // Disparar validación
    }
    
    if (emailInput && !emailInput.value && user.email) {
        emailInput.value = user.email;
        validarEmail(); // Disparar validación
        datosReserva.email = user.email;
    }
    
    // Guardar en localStorage para futuras visitas
    if (user) {
        localStorage.setItem('usuario', JSON.stringify({
            uid: user.uid,
            nombre: user.displayName,
            email: user.email,
            telefono: user.phoneNumber || ''
        }));
    }
}


// Función para verificar si el usuario es administrador (dueño o delegado
// del negocio actual). Antes comparaba contra un único UID hardcodeado,
// después contra un único ownerUid por negocio; ahora cada negocio tiene
// una LISTA de administradores (negocios/{negocioId}.adminsUids) — mismo
// criterio que esEsteUsuarioOwnerDelNegocio en admin.js, duplicado acá
// porque esta función corre en el sitio público (index.html), no en el
// panel. ownerUid queda de respaldo para negocios creados antes de que
// existiera adminsUids.
async function esUsuarioAdministrador(user) {
    if (!user) return false;
    try {
        const negocioDoc = await window.db.collection('negocios').doc(obtenerNegocioIdActual()).get();
        if (!negocioDoc.exists) return false;
        const negocio = negocioDoc.data();
        return Array.isArray(negocio.adminsUids) ? negocio.adminsUids.includes(user.uid) : negocio.ownerUid === user.uid;
    } catch (error) {
        console.error('Error verificando si el usuario es administrador:', error);
        return false;
    }
}

async function actualizarBotonAdmin(user) {
    const botonesAdmin = document.querySelectorAll('.btn-admin');
    const esAdmin = await esUsuarioAdministrador(user);

    botonesAdmin.forEach(btn => {
        btn.style.display = esAdmin ? 'block' : 'none';
    });
}

// Función para mostrar mensajes de éxito (toast esquina superior derecha,
// con barra de progreso — mismo patrón que ya usa el panel admin)
function mostrarMensajeExito(mensaje) {
    // Quitar uno anterior si estaba visible, para reiniciar la animación
    const anterior = document.getElementById('mensaje-exito');
    if (anterior) anterior.remove();

    const mensajeExito = document.createElement('div');
    mensajeExito.id = 'mensaje-exito';
    mensajeExito.className = 'mensaje-exito';

    mensajeExito.innerHTML = `
        <div class="mensaje-contenido">
            <svg class="icono-check-notificacion" viewBox="0 0 24 24" width="24" height="24">
                <path d="M9 16.17L4.83 12l-1.42 1.41L9 19 21 7l-1.41-1.41z"/>
            </svg>
            <span>${mensaje}</span>
            <div class="barra-progreso-notificacion"></div>
        </div>
    `;

    document.body.appendChild(mensajeExito);

    // Mostrar con animación (el pequeño delay permite que la transición corra)
    setTimeout(() => {
        mensajeExito.classList.add('visible');
    }, 10);

    // Ocultar y eliminar después de 5 segundos (dura lo mismo que la barra)
    setTimeout(() => {
        mensajeExito.classList.remove('visible');
        setTimeout(() => {
            if (mensajeExito.parentNode) {
                mensajeExito.remove();
            }
        }, 300);
    }, 5000);
}

