// Función para manejar el estado de autenticación en el menú
function actualizarVisibilidadMenu(user) {
    const elementosAuth = document.querySelectorAll('.nav-item-auth');
    const elementosNoAuth = document.querySelectorAll('.nav-item-no-auth');
    
    if (user) {
        elementosAuth.forEach(item => item.style.display = 'block');
        elementosNoAuth.forEach(item => item.style.display = 'none');
    } else {
        elementosAuth.forEach(item => item.style.display = 'none');
        elementosNoAuth.forEach(item => item.style.display = 'block');
    }
    
    // Re-inicializar el acordeón para los nuevos elementos
    setTimeout(() => {
        inicializarAcordeonMenu();
    }, 100);
}

